#include <algorithm>
#include <vector>

std::vector<int> uniqueSorted(std::vector<int> values)
{
    std::sort(values.begin(), values.end());
    values.erase(std::unique(values.begin(), values.end()), values.end());
    return values;
}

unitTests:
TEST("removes duplicates and sorts") { CHECK_EQ(uniqueSorted({ 3, 1, 3, 2, 1 }), (std::vector<int>{ 1, 2, 3 })); }
TEST("already unique") { CHECK_EQ(uniqueSorted({ 9, 7, 8 }), (std::vector<int>{ 7, 8, 9 })); }
TEST("all the same") { CHECK_EQ(uniqueSorted({ 4, 4, 4, 4 }), (std::vector<int>{ 4 })); }
TEST("empty") { CHECK(uniqueSorted({}).empty()); }

